data.minimal_example:
FlashyFlushbar(
  leadingWidget: const Icon(
    Icons.error_outline,
    color: Colors.black,
    size: 24,
  ),
  message: 'Hello from Flashy Flushbar',
  duration: const Duration(seconds: 1),
  trailingWidget: IconButton(
    icon: const Icon(
      Icons.close,
      color: Colors.black,
      size: 24,
    ),
    onPressed: () {
      FlashyFlushbar.cancel();
    },
  ),
  isDismissible: false,
).show();
